use crate::db::{CreateMeasurementUnitInput, Database, MeasurementUnit}; use tauri::State;
#[tauri::command] pub async fn get_measurement_units(company_id:String, db:State<'_,Database>)->Result<Vec<MeasurementUnit>,String>{sqlx::query_as("SELECT * FROM measurement_units WHERE company_id=? ORDER BY unit_name").bind(company_id).fetch_all(db.pool()).await.map_err(|e|format!("查询计量单位失败: {e}"))}
#[tauri::command] pub async fn create_measurement_unit(input:CreateMeasurementUnitInput,db:State<'_,Database>)->Result<MeasurementUnit,String>{if input.unit_name.trim().is_empty()||input.conversion_rate<=0.0||input.precision_digits<0{return Err("单位名称不能为空，换算率必须大于零".into())}let id=uuid::Uuid::new_v4().to_string();sqlx::query("INSERT INTO measurement_units (id,company_id,unit_name,unit_group,base_unit,conversion_rate,precision_digits,remark) VALUES (?,?,?,?,?,?,?,?)").bind(&id).bind(&input.company_id).bind(input.unit_name.trim()).bind(input.unit_group).bind(input.base_unit).bind(input.conversion_rate).bind(input.precision_digits).bind(input.remark).execute(db.pool()).await.map_err(|e|format!("新增计量单位失败: {e}"))?;sqlx::query_as("SELECT * FROM measurement_units WHERE id=?").bind(id).fetch_one(db.pool()).await.map_err(|e|format!("查询新增计量单位失败: {e}"))}
